/** Repository root, so a localCopy path can be resolved for hash verification from anywhere. */
const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");

export const SOURCE_TIERS = Object.freeze(["controlling", "guidance", "contextual"]);
export const GAP_TIERS = Object.freeze(["controlling", "guidance", "identified-not-taught"]);

/**
 * A Texas code chapter. `tier` defaults to "controlling": a Texas chapter is registered here only
 * because a read record names sections of it that a module teaches as law. Anything else must say so.
 */
const chapter = (record) =>
  Object.freeze({
    ...record,
    id: `${record.code.toLowerCase()}-${record.chapter}`,
    citation: `Tex. ${record.codeName} ch. ${record.chapter}`,
    publisher: "Texas Legislative Council",
    sourceLayer: "tcss.legis.texas.gov static resources",
    jurisdiction: "texas",
    tier: record.tier ?? "controlling",
    reliedOnByUnits: Object.freeze(record.reliedOnByUnits),
    sectionsRead: Object.freeze(record.sectionsRead),
  });

/** A federal statute or regulation. Same default, same reason; the two contextual ones say so. */
const federal = (record) =>
  Object.freeze({
    ...record,
    id: record.citation.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""),
    jurisdiction: "federal",
    tier: record.tier ?? "controlling",
    reliedOnByUnits: Object.freeze(record.reliedOnByUnits),
    sectionsRead: Object.freeze(record.sectionsRead),
  });

