/* ────────────────────────────────────────────────────────────────────────────────────────────────
 * TREC ADMINISTRATIVE RULES — 22 TAC ch. 535, CONNECTED rather than restated.
 *
 * The five rule sections are held on disk with hashes in config/texas/trec-rules-source-lock.mjs.
 * That file is the authority for their localCopy, sha256 and byte count and this register does not
 * re-declare any of them: trecRule() looks each rule up by section and copies the lock's own values.
 * What this register adds is the read-record layer the lock does not carry — which module opened the
 * rule, which units rely on it, and what proposition each module took from it — plus, for the two
 * rules the course's ASSESSMENT and COMPLIANCE logic depends on rather than its text, the artefacts
 * that depend on them.
 *
 * Note the tier reasoning, because it is the point of the whole exercise: 22 TAC §§ 535.62 and
 * 535.65 are CONTROLLING even though no module quotes them to a student. Every assessment number
 * this course is built to — three questions per topic quiz, three scenario exercises, four
 * examination versions, 60 questions per version, a 120-question bank, no true/false items, the
 * one-third cross-version overlap cap and the 70% unweighted passing score — is derived in
 * ASSESSMENT_REQUIREMENTS from § 535.62(b)(7) and § 535.65. Occupations Code ch. 1101 does not
 * contain any of those numbers, and treating the statute as a substitute for the rule would be a
 * false statement of where the requirement comes from.
 * ──────────────────────────────────────────────────────────────────────────────────────────────── */

const trecRule = (record) => {
  const locked = TREC_RULES.find((entry) => entry.section === record.section);
  if (!locked) {
    throw new Error(`principles-ii-statute-sources: 22 TAC ${record.section} is not in trec-rules-source-lock RULES`);
  }
  return Object.freeze({
    ...record,
    id: `tac-535-${locked.section.split(".").pop()}`,
    citation: locked.section,
    title: locked.heading,
    authority: "Texas Real Estate Commission",
    publisher: TREC_RULES_SOURCE.authority,
    sourceLayer: TREC_RULES_SOURCE.title,
    url: TREC_RULES_SOURCE.url,
    /* Imported, never re-declared. */
    localCopy: locked.localCopy,
    sha256: locked.sha256,
    bytes: locked.bytes,
    retrievedOn: TREC_RULES_SOURCE.readOn,
    governs: locked.governs,
    provisionIds: Object.freeze(locked.provisions.map((provision) => provision.id)),
    codifiedTextCompared: TREC_RULES_SOURCE.codifiedTextCompared,
    jurisdiction: "texas",
    tier: record.tier ?? "controlling",
    reliedOnByUnits: Object.freeze(record.reliedOnByUnits),
    reliedOnByArtifacts: Object.freeze(record.reliedOnByArtifacts ?? []),
    sectionsRead: Object.freeze(record.sectionsRead),
  });
};

