/* ────────────────────────────────────────────────────────────────────────────────────────────────
 * TREC GUIDANCE — imported from the regulatory manifest, which already holds its hash.
 * ──────────────────────────────────────────────────────────────────────────────────────────────── */

const manifestSource = (id) => {
  const found = REGULATORY_SOURCES.find((entry) => entry.id === id);
  if (!found) throw new Error(`principles-ii-statute-sources: manifest source '${id}' not found in regulatory-manifest SOURCES`);
  return found;
};

const guidance = (record) => {
  const manifest = manifestSource(record.manifestSourceId);
  return Object.freeze({
    ...record,
    id: manifest.id,
    citation: `TREC, "${manifest.title}"`,
    title: manifest.title,
    authority: manifest.authority,
    publisher: manifest.authority,
    url: manifest.url,
    /* Imported, never re-declared. */
    localCopy: manifest.localCopy,
    sha256: manifest.sha256,
    effectiveDate: manifest.effectiveDate,
    retrievedOn: manifest.readOn,
    manifestPrecedence: manifest.precedence,
    materialClaimIds: Object.freeze(manifest.materialClaims.map((claim) => claim.id)),
    jurisdiction: "texas",
    tier: "guidance",
    reliedOnByUnits: Object.freeze(record.reliedOnByUnits),
    sectionsRead: Object.freeze(record.sectionsRead),
  });
};

