export const ALL_SOURCES = Object.freeze([
  ...STATUTE_CHAPTERS,
  ...CONSTITUTIONAL_SOURCES,
  ...FEDERAL_SOURCES,
  ...TREC_RULE_SOURCES,
  ...GUIDANCE_SOURCES,
]);

/* Structural invariants, asserted at import so a later edit cannot quietly break them. */
{
  const ids = ALL_SOURCES.map((entry) => entry.id);
  const duplicate = ids.find((id, index) => ids.indexOf(id) !== index);
  if (duplicate) throw new Error(`principles-ii-statute-sources: duplicate source id '${duplicate}'`);
  const untiered = ALL_SOURCES.filter((entry) => !SOURCE_TIERS.includes(entry.tier));
  if (untiered.length) throw new Error(`principles-ii-statute-sources: source(s) without a valid tier: ${untiered.map((e) => e.id).join(", ")}`);
  const unhashed = ALL_SOURCES.filter((entry) => !entry.localCopy || !entry.sha256 || !entry.bytes);
  if (unhashed.length) throw new Error(`principles-ii-statute-sources: source(s) registered without a local copy, hash or byte count: ${unhashed.map((e) => e.id).join(", ")}`);
}

/**
 * The honest counterpart to the register: the substantive gaps the read records record — things the
 * course had to teach around because no source was held for them.
 *
 * `affectedUnits` names a unit only where the record supports it: either the record's own gap text
 * names the unit, or the gap was recorded under a SOURCE block, in which case the units relying on
 * that source are named. Where a record states a gap at topic level without tying it to a unit, the
 * array is deliberately EMPTY rather than filled in by inference.
 *
 * `gapTier` says what kind of hole each one is:
 *   "controlling"          — a binding source the course RELIES ON but does not hold. This category
 *                            must be, and is, EMPTY. A gap belongs here only where a taught
 *                            proposition rests on a source that is not held; naming a source in
 *                            order to say the course does not teach it is not reliance.
 *   "guidance"             — regulator-published explanatory material or a regulator form that the
 *                            course describes only through the statute because the item itself is
 *                            not held.
 *   "identified-not-taught" — named in the course expressly to say it is NOT taught, or a topic the
 *                            course teaches as practice while saying no source supports it. These
 *                            entries are correct as they stand and are meant to survive.
 */
