/* The category that must stay empty, asserted rather than described. */
{
  const invalid = GAPS.filter((entry) => !GAP_TIERS.includes(entry.gapTier));
  if (invalid.length) throw new Error(`principles-ii-statute-sources: gap(s) without a valid gapTier: ${invalid.map((e) => e.id).join(", ")}`);
  const controlling = GAPS.filter((entry) => entry.gapTier === "controlling");
  if (controlling.length) {
    throw new Error(
      `principles-ii-statute-sources: a controlling source the course relies on is not held: ${controlling.map((e) => e.id).join(", ")}. ` +
        "Hold and register the source, or establish that the course does not rely on it.",
    );
  }
}

export const SECTIONS_READ = Object.freeze(
  ALL_SOURCES.flatMap((entry) => entry.sectionsRead.map((s) => Object.freeze({ ...s, sourceId: entry.id, jurisdiction: entry.jurisdiction, tier: entry.tier, citation: entry.citation }))),
);

/** Every PRINS2-1 unit either has a source read for it or is named as needing none. */
export function unitCoverage(allUnitCodes) {
  const held = new Set(ALL_SOURCES.flatMap((entry) => entry.reliedOnByUnits));
  const excused = new Set(NO_STATUTE_REQUIRED.map((entry) => entry.unit));
  return Object.freeze({
    held: Object.freeze(allUnitCodes.filter((code) => held.has(code))),
    excused: Object.freeze(allUnitCodes.filter((code) => !held.has(code) && excused.has(code))),
    uncovered: Object.freeze(allUnitCodes.filter((code) => !held.has(code) && !excused.has(code))),
  });
}

